def seconds_to_min_sec(seconds):
    m, s = divmod(seconds, 60)
    return f"{m}:{s:02d}"

def hms_to_seconds_signed(s):
    sign = 1
    if s.startswith('-'):
        sign = -1
        s = s[1:]
    h, m, sec = map(int, s.split(':'))
    return sign * (h * 3600 + m * 60 + sec)

