def days_until_next_birthday(birth_md, today_ymd):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_before_year(y):
        y -= 1
        return y * 365 + y // 4 - y // 100 + y // 400

    def days_before_month(y, m):
        cum = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        res = cum[m - 1]
        if m > 2 and is_leap(y):
            res += 1
        return res

    def to_ordinal(y, m, d):
        return days_before_year(y) + days_before_month(y, m) + d

    month, day = birth_md
    y, m, d = today_ymd
    today_ord = to_ordinal(y, m, d)
    cand_ord = to_ordinal(y, month, day)
    if cand_ord < today_ord:
        cand_ord = to_ordinal(y + 1, month, day)
    return cand_ord - today_ord

