def nth_weekday_of_month(year, month, weekday_num, n):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_before_year(y):
        y -= 1
        return y * 365 + y // 4 - y // 100 + y // 400

    def days_before_month(y, m):
        cum = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        res = cum[m - 1]
        if m > 2 and is_leap(y):
            res += 1
        return res

    def to_ordinal(y, m, d):
        return days_before_year(y) + days_before_month(y, m) + d

    def weekday(y, m, d):
        return (to_ordinal(y, m, d) - 1) % 7

    first_wd = weekday(year, month, 1)
    offset = (weekday_num - first_wd) % 7
    first_occurrence = 1 + offset
    return first_occurrence + (n - 1) * 7

def count_weekday_occurrences_in_month(year, month, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_before_year(y):
        y -= 1
        return y * 365 + y // 4 - y // 100 + y // 400

    def days_before_month(y, m):
        cum = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]
        res = cum[m - 1]
        if m > 2 and is_leap(y):
            res += 1
        return res

    def to_ordinal(y, m, d):
        return days_before_year(y) + days_before_month(y, m) + d

    def weekday(y, m, d):
        return (to_ordinal(y, m, d) - 1) % 7

    def days_in_month(y, m):
        dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        return dim[m - 1]

    first_wd = weekday(year, month, 1)
    offset = (weekday_num - first_wd) % 7
    first_occurrence = 1 + offset
    dim = days_in_month(year, month)
    return (dim - first_occurrence) // 7 + 1
